local h = {
	Query = 1,
	Action = 2,
	Validate = 3,
}

return function(Plasma)
	local create = Plasma.create

	local Item = Plasma.widget(function(text, selected, icon, sideText, width)
		local clicked, setClicked = Plasma.useState(false)
		local style = Plasma.useStyle()
		local refs = Plasma.useInstance(function(ref)
			local button = create("TextButton", {
				[ref] = "button",
				Size = UDim2.new(.9, 0, 0, 40),
				Text = "",
				BackgroundTransparency = .5,
				Position = UDim2.fromScale(1, 0),
				AnchorPoint = Vector2.new(1, 0),
				
				create("UICorner", {
					CornerRadius = UDim.new(0, 8),
				}),

				create("UIPadding", {
					PaddingBottom = UDim.new(0, 0),
					PaddingLeft = UDim.new(0, 8),
					PaddingRight = UDim.new(0, 8),
					PaddingTop = UDim.new(0, 0),
				}),

				create("UIListLayout", {
					SortOrder = Enum.SortOrder.LayoutOrder,
					FillDirection = Enum.FillDirection.Horizontal,
					Padding = UDim.new(0, 10),
				}),

				create("TextLabel", {
					Name = "Icon",
					BackgroundTransparency = 1,
					Size = UDim2.new(0, 22, 1, 0),
					Text = icon,
					TextXAlignment = Enum.TextXAlignment.Left,
					TextSize = 21,
					TextColor3 = style.textColor,
					Font = Enum.Font.GothamBold,
				}),

				create("TextLabel", {
					AutomaticSize = Enum.AutomaticSize.X,
					BackgroundTransparency = 1,
					Size = UDim2.new(0, 0, 1, 0),
					Text = text,
					TextXAlignment = Enum.TextXAlignment.Left,
					TextSize = 21,
					TextColor3 = style.textColor,
					Font = Enum.Font.GothamBold,
					-- TextTruncate = Enum.TextTruncate.AtEnd,

					create("UISizeConstraint", {
						MaxSize = Vector2.new(165, math.huge),
					}),
				}),

				create("TextLabel", {
					[ref] = "sideText",
					BackgroundTransparency = 1,
					AutomaticSize = Enum.AutomaticSize.X,
					Size = UDim2.new(0, 0, 1, 0),
					Text = "",
					TextXAlignment = Enum.TextXAlignment.Left,
					TextSize = 15,
					TextColor3 = style.mutedTextColor,
					Font = Enum.Font.SourceSans,
				}),

				Activated = function()
					setClicked(true)
				end,
			})

			return button
		end)

		Plasma.useEffect(function()
			refs.button.TextLabel.Text = text
			refs.button.Icon.Text = icon or ""
			refs.button.Icon.Visible = not not icon
		end, text, icon)
		
		refs.sideText.Visible = not not sideText
		refs.sideText.Text = sideText or ""
		refs.sideText.TextColor3 = if selected then style.textColor else style.mutedTextColor
		-- refs.button.TextLabel.TextTruncate = sideText and Enum.TextTruncate.AtEnd or Enum.TextTruncate.None

		Plasma.useEffect(function()
			refs.button.BackgroundColor3 = if selected then style.primaryColor else style.bg2
		end, selected)

		return {
			clicked = function()
				if clicked then
					setClicked(false)
					return true
				end

				return false
			end,
		}
	end)

	return Plasma.widget(function(header, items, options)
		options = options or {}
		local refs = Plasma.useInstance(function(ref)
			local style = Plasma.useStyle()
			local frame = create("Frame", {
				Name = header .. "Group",
				Position = UDim2.new(0, 0, 0, 0),
				Size = UDim2.new(0, 270, 0, 0),
				AutomaticSize = Enum.AutomaticSize.Y,
				BackgroundTransparency = 1,
				create("UICorner"),
				create("UIPadding", {
					PaddingBottom = UDim.new(0, 8),
					PaddingLeft = UDim.new(0, 8),
					PaddingRight = UDim.new(0, 8),
					PaddingTop = UDim.new(0, 8),
				}),
				create("UIListLayout", {
					SortOrder = Enum.SortOrder.LayoutOrder,
					HorizontalAlignment = Enum.HorizontalAlignment.Right,
					Padding = UDim.new(0, 8)
				}),
				create("TextButton", {
					[ref] = "header",
					Font = Enum.Font.GothamBold,
					AutomaticSize = Enum.AutomaticSize.Y,
					TextColor3 = style.mutedTextColor,
					TextSize = 21,
					RichText = true,
					Text = "Validate",
					BackgroundTransparency = 0,
					BackgroundColor3 = style.bg2,
					Size = UDim2.fromScale(1, 0),
					TextXAlignment = Enum.TextXAlignment.Left,
					create("UIPadding", {
						PaddingTop = UDim.new(0, 8),
						PaddingBottom = UDim.new(0, 8),
						PaddingLeft = UDim.new(0, 8),
						PaddingRight = UDim.new(0, 8),
					}),
					create("UICorner"),
				})
			})
			ref.rect = frame
			return frame
		end)

		refs.header.Text = header
		refs.rect.LayoutOrder = h[header]
		local selected
		for _, item in items do
			if Item(item.text, item.selected, item.icon, item.sideText, options.width):clicked() then
				-- print(h, item.text)
				selected = item
			end
			-- custom.operationGroup(key, groupItem)
		end

		return {
			selected = function()
				return selected
			end,
		}
	end)
end
